{"cards": [{"node_code": "N_5e9d57510a717377", "definition": "研究微循环系统中毛细血管及微血管结构、通透性异常及其相关疾病诊疗的学科，涵盖微血管病变、渗漏及微血栓形成。", "boundary": "本节点聚焦直径最小的血管单位（毛细血管、微动脉、微静脉）的病理改变。包括糖尿病微血管病变、过敏性紫癜、毛细血管扩张症及微循环障碍。不包含大动脉或大静脉的结构性病变（如动脉瘤、深静脉血栓），也不包含单纯的红细胞或血小板异常导致的出血/凝血障碍。", "includes": ["微血管病变（如糖尿病视网膜病变、肾病中的微血管损伤）", "毛细血管通透性异常（如过敏性紫癜、血管性水肿）", "微循环障碍及微血栓形成"], "excludes": ["大动脉粥样硬化或夹层（归入动脉疾病）", "大静脉血栓或静脉曲张（归入静脉疾病）"], "sibling_distinctions": [{"other_code": "N_67f796f14e06b4d1", "rule": "本节点关注微血管（毛细血管）层面的病变；动脉疾病关注中、大动脉的结构与功能异常。"}, {"other_code": "N_c9ae15fae0c4d089", "rule": "本节点关注微血管层面的病变；静脉疾病关注中、大静脉的血流动力学及结构异常。"}], "cross_boundary_rule": "若病变主要累及微循环且表现为通透性增加或微血栓，归入本节点；若累及较大血管主干，则归入相应的动脉或静脉疾病节点。"}, {"node_code": "N_7dc52d4ff4c65459", "definition": "研究肺循环系统中肺动脉、肺静脉及其分支结构、功能异常及其疾病诊疗的学科，涵盖肺血管高压、栓塞及畸形。", "boundary": "本节点特指位于肺部的血管病变，包括肺动脉高压、肺栓塞、肺动静脉瘘及肺静脉回流异常。不包含肺部实质性疾病（如肺炎、肺癌），也不包含体循环的动脉或静脉疾病。肺栓塞虽常由下肢静脉血栓引起，但因其病理后果主要发生在肺血管，故归入本节点。", "includes": ["肺动脉高压（原发性或继发性）", "肺栓塞及肺血管畸形（如肺动静脉瘘）", "肺静脉回流异常及肺血管炎"], "excludes": ["肺部实质性疾病（如肺炎、哮喘、肺癌）", "体循环动脉或静脉疾病（如冠心病、下肢静脉曲张）"], "sibling_distinctions": [{"other_code": "N_67f796f14e06b4d1", "rule": "本节点特指肺循环血管；动脉疾病主要指体循环动脉（如主动脉、冠状动脉、外周动脉）。"}, {"other_code": "N_c9ae15fae0c4d089", "rule": "本节点特指肺循环静脉；静脉疾病主要指体循环静脉（如下肢深静脉、颈静脉）。"}], "cross_boundary_rule": "肺栓塞主挂载于本节点，因其直接损害肺血管床；若重点讨论下肢深静脉血栓的形成机制，可关联静脉疾病，但临床后果及肺血管管理归入本节点。"}, {"node_code": "N_c9ae15fae0c4d089", "definition": "研究体循环静脉系统结构、血流动力学异常及其疾病诊疗的学科，涵盖静脉血栓、静脉曲张及静脉炎。", "boundary": "本节点聚焦体循环静脉（如下肢、上肢、颈部、腹部静脉）的病变，包括深静脉血栓形成（DVT）、浅静脉曲张、静脉炎及静脉功能不全。不包含肺静脉病变（归入肺动、静脉疾病），也不包含动脉系统疾病。", "includes": ["深静脉血栓形成（DVT）及浅静脉血栓", "静脉曲张及静脉功能不全", "静脉炎及静脉畸形"], "excludes": ["肺静脉病变（归入肺动、静脉疾病）", "动脉系统疾病（如动脉粥样硬化、动脉瘤）"], "sibling_distinctions": [{"other_code": "N_67f796f14e06b4d1", "rule": "本节点关注静脉系统（低压力、回流方向）；动脉疾病关注动脉系统（高压力、流出方向）。"}, {"other_code": "N_7dc52d4ff4c65459", "rule": "本节点关注体循环静脉；肺动、静脉疾病特指肺循环中的静脉病变。"}], "cross_boundary_rule": "下肢深静脉血栓若导致肺栓塞，主挂载于肺动、静脉疾病（因后果严重性），但血栓本身的形成与局部静脉病变管理可关联本节点。"}]}
